CREATE TABLE iu_moments (
 id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK (kind IN ('op','simulator')),
 section TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',
 max_score INTEGER CHECK (max_score BETWEEN 0 AND 1000),position INTEGER NOT NULL,
 deleted_at BIGINT,updated_at BIGINT NOT NULL,updated_by TEXT NOT NULL
);
CREATE INDEX iu_moments_active ON iu_moments(position) WHERE deleted_at IS NULL;
INSERT INTO iu_moments(id,kind,section,title,description,max_score,position,updated_at,updated_by) VALUES
('op-1','op','op','Avspärrning','Korrekt avspärrat. Sista signalen får inte visa kör/lodrätt.
Exempel fråga: Om ett skydd använder medriktad signal som gränspunkt, hur avspärrar du? = Ej använda gränspunkt som spärråtgärd.',NULL,1,0,'initial'),
('op-2','op','op','Växling','Muntlig överenskommelse. Korrekt starttillstånd samt dokumentation.
Exempel fråga: Om en växling vill utöka sitt växlingsområde, hur gör du då? = Ny avstämning och nytt starttillstånd för växlingen.',NULL,2,0,'initial'),
('op-3','op','op','Växling utanför växlingsgräns','Korrekt dokumentation.
Exempel fråga: Vad blir skillnaden i dokumentation om växling utanför växlingsgränsen sker på kör/avspärrad bevakningssträcka? = Blyertsbåge vid kör, rött streck vid avspärrat.',NULL,3,0,'initial'),
('op-4','op','op','Spärrfärd','Planering. Ev. samråd. Sträckorder. Korrekt starttillstånd samt dokumentation. Korrekt avspärrning.
Exempel fråga: Om du har en spärrfärd ute på en sträcka med mellanblocksignaler och ett A-skydd vill komma ut på samma sträcka, hur hanterar du det? = Efter OK av samråd – även LIS i andra änden.',NULL,4,0,'initial'),
('op-5','op','op','Skyddsformer','Planering. Dokumentation. Samråd. Avstämning. Avspärrning. Bekr kortslutning. Starttillstånd.
Exempel fråga: Om du har fler än en anordning på samma sträcka, hur dokumenterar du det? = Båda ska finnas i skydd & färder.',NULL,5,0,'initial'),
('op-6','op','op','Småfordon','Förstår risker med småfordon. Använder rätt skyddsåtgärder.
Exempel fråga: Om en spärrfärd småfordon vill starta från driftplats X hur gör du då? = Stäm av',NULL,6,0,'initial'),
('op-7','op','op','Spärrfärd hjälpfordon','Begäran på BL 22. Återkallar körtillstånd. Planerar på BL 29. Dokumentation. Korrekt avspärrning.
Exempel fråga: Får vi köra ut en spärrfärd hjälpfordon på kör i system H? = Ja, samma som vanlig spärrfärd.',NULL,7,0,'initial'),
('op-8','op','op','Ordergivning','Dokumentation. Kvittera order. Ordergivnings driftplats. Tågorder med körplan.
Exempel fråga: Om det här vägskyddet börjar larma säkerhetsfel, hur gör du då? = Dokumenterar i graf. Orderger om felaktigt vägskyddsanläggning.',NULL,8,0,'initial'),
('op-9','op','op','HAU','Tar reda på information. Påminnelseåtgärd. Dokumentation. Felanmälan. Ordergivning.
Exempel fråga: Tåg X ringer in om dåligt spårläge, bedömer ok att köra 45. Vad blir dina åtgärder? = Avspärra. Dokumentera HAU 40. Felanmälan. Ordergivning. Meddela info.',NULL,9,0,'initial'),
('op-10','op','op','Balisfel','Felanmälan. Ordergivning.
Exempel fråga: Vad för balisfel finns det och i vilken riktning orderger vi? = Balisinformationsfel i båda riktningar, balisöverrensstämmelsefel i den riktning felet inträffade.',NULL,10,0,'initial'),
('op-11','op','op','Hjulskada/Varmgång','Akut hantering. Detektorlarm. Manuellt upptäckt. HAU övriga färder. Avsyning.
Exempel fråga: Manuellt upptäckt hjulskada, vad blir omfattningen på HAU för andra färder? = 2+1',NULL,11,0,'initial'),
('op-12','op','op','Backning','Förstår risker med backning. Med eller utan uppsikt. Andra färder. Vägskyddsanläggningar. Linjen eller på driftplats.
Exempel fråga: Hur kan vi säkra backningssträckan på driftplats? = Tåg/växlingsväg eller avspärra.',NULL,12,0,'initial'),
('op-13','op','op','Stoppställa signal/Nödutlösa tågväg','Fara. Stillastående färd. Ta tillbaka tågvägslåsning.
Exempel fråga: Hitta tåg operativt och fråga är det ok att stoppställa signal/nödutlösa tågväg = OK vid fara att stoppställa. Om föraren meddelar att hen hinner stanna. Ej ta tillbaka tågvägslåsning förens föraren bekräftar att hen står still/ej nåtts av beskedet.',NULL,13,0,'initial'),
('op-14','op','op','Ställverkskunskap','Olikheter mellan ställverken. Enstaka objekt eller i grupp. Låsa växlar. Reservera spåravsnitt.
Exempel fråga: Är en magenta/rosa växel låst? = Nej, den är endast spärrad i manöversystemet för oss, ställverket kan ändå lägga om denna växel.',NULL,14,0,'initial'),
('op-15','op','op','Stoppkörning','Kontroller. Växlars läge. Rätt ifylld blankett 21.
Exempel fråga: När får du kombinera msi + ublsi förr norrgående tåg i Hällnäs?  = När vi kan låsa växeln (så inte tåget kan komma ut på fel bevakningssträcka).',NULL,15,0,'initial'),
('op-16','op','op','Stoppkörning spärrfärd','Inte växling samtidigt. Kombinera flera signaler på samma blankett. Växlars läge vid samråd (enligt villkor från tsm/htsm).
Exempel fråga: Vilka signaler får du ge på samma blankett 21 för spärrfärd = Vid uppfyllda villkor ok att kombinera msi + ublsi. EJ efterföljande mellanblocksignaler.',NULL,16,0,'initial'),
('op-17','op','op','Stoppkörning växling','Enstaka dvärgsignaler. Flera huvudsignaler.
Exempel fråga: Vad ska vara uppfyllt för att ge tillstånd att passera samtliga mellansignaler i stopp? = Lokalfrigivet hela driftplatsen och kan ske utan fara.',NULL,17,0,'initial'),
('op-18','op','op','Skred','Nödanrop till tåg. Meddela tsm/htsm. Trafikstopp. Dokumentation. Felanmälan.
Exempel fråga: Skredlarm har gått med tåg på sträckan, efter kontroller beslutar vi att tåget får fortsätta till nästa driftplats. Vilken hastighet gäller? = 20 km/h',NULL,18,0,'initial'),
('op-19','op','op','R-Växel','Ur kontroll. Beläggning. Tsm på plats. Klovad.
Exempel fråga: Om en växel är vit för oss, behörig felavhjälpare är på plats som bekräftar att växeln ligger rätt, ej lokalt. Vad skriver vi på BL21 till färder som ska passera? = Kontrollera växlarna.',NULL,19,0,'initial'),
('op-20','op','op','Haparanda larm','Larmhantering. Kodord Alfa, Bravo, Charlie. Egen checklista i BOTA.
Exempel fråga:  Om Finland ringer med kod Charlie till oss, vad betyder det? = Att de inte längre ser ett behov av trafikstopp på svenskt område (betyder inte att vi kan börja köra tåg i Haparanda).',NULL,20,0,'initial'),
('op-21','op','op','Spärrfärd/Skydd efter tåg','Planering. Ankomstanmälan. Slutsignal. Starttillstånd.
Exempel fråga: Får en spärrfärd gå som ”efter tåg” sträckan HLS – ÅM om tåget är ett resandetåg = Nej. Eftersom spärrfärd efter resande tåg endast får omfatta del av bevakningssträckan.',NULL,21,0,'initial'),
('op-22','op','op','Sena/Tidiga tåg (Nya k-möten)','Exempel fråga: Om tåg 1 & 2 har k-möte i B men tåg 2 blir inställt, vad blir ordergivningen för tåg 1?  = Slopat k-möte för tåg 1.',NULL,22,0,'initial'),
('op-23','op','op','HAU system M','Exempel fråga:  Om förare bedömer dåligt spårläge inne i Skl, går att trafikera 40. Hur blir ordergivningen då från Söv? = Söv-Ffs. Eftersom orsaken är inne i obevakad dp (eller lp) ska nedsättningssträckan omfatta också linjen fram till följande dp eller lp.',NULL,23,0,'initial'),
('op-24','op','op','Spärrfärd hjälpfordon system M','Exempel fråga: Vad är skillnaden från system H? = Får ange var tåget befinner sig i större grad. Om tåget befinner sig i sin helhet inne på obevakad dp/lp får denna anges. Annars begränsa med närmaste dp/lp.',NULL,24,0,'initial'),
('op-25','op','op','K16 Gunsen','Vad är risken? Var finns regeln beskriven. Ankomstanmälan Skellefteå. Samråd – inte OK ändå.
Exempel fråga: Får en spärrfärd befinna sig mellan Söv-Skl trots att K16 används i Gunsen av ett A-s om de haft samråd? = Nej.',NULL,25,0,'initial'),
('op-26','op','op','E2 spärråtgärder','Spärra signalpunkter/dvsi. Spärra spåravsnitt. Låsa växlar i skyddande läge. Upplåsningspärrad tågväg
Exempel fråga: Om en spärrfärd på Haparandabanan ska anordnas för att förflytta sig från X – X. Hur kan vi avspärra för den? = Upplåsningspärrad tågväg. Sis i utfartssignalpunkterna.',NULL,26,0,'initial'),
('op-27','op','op','Nödstopp','Exempel fråga: Vad får föraren inte göra innan vi skrivit blankett vid nödstopp? = Trycka start',NULL,27,0,'initial'),
('op-28','op','op','Okänd position','Exempel fråga: Vad ska vi kontrollera innan vi positionerar ett tåg? = Finns med i listan över tåg i okänd position, positionen föraren anger är rimlig.',NULL,28,0,'initial'),
('op-29','op','op','Muntligt körtillstånd i andra situationer','Exempel fråga: Hur hanterar du en växel ur kontroll + stoppkörning i infsi/msi E2 = Förenklad tågväg+ kontroller: Sträckan fram till nästa signalpunkt ska vara – fri från andra trafikverksamheter, fri från andra fordon än avsiktligt uppställda, endast felaktiga beläggningar.',NULL,29,0,'initial'),
('op-30','op','op','Tappad kontakt med RBC','Exempel fråga: Tappad kontakt, långt ifrån näsa signalpunkt, hur går du till väga? = Omstart av lok, lås upp väg under tåget, reservera med förenklad tågväg, BL 01, får gå fram till signalpunkt.',NULL,30,0,'initial'),
('op-31','op','op','Kvittera ”På-sikt”','Exempel fråga: Nämn ett exempel då det kan vara aktuellt att medge driftläge på sikt? = Felaktig beläggning, hjälpfordon, tillkoppling.',NULL,31,0,'initial'),
('op-32','op','op','Förprojekterad akut nedsättning','Exempel fråga: Hur gör du en akut nedsättning? = Klicka på en spårledning där nedsättningen ska gälla (blir hela dp eller linjen). Aktivera akut nedsättning. Orderge första tåget om att kontrollera att den ligger rätt. Fortsatt ordergivning om att det är en nedsättning där (om den inte finns i körorder).',NULL,32,0,'initial'),
('op-33','op','op','Systemstopp','Exempel fråga: Nämn en sak du ska kontrollera efter systemstopp = Kontrollera att samtliga är korrekt: Sträckor/objekt ska vara spärrade, områden som ska vara lokalreserverade, nödstoppsområden, särskilda och upplåsningspärrade tågvägar, positioner på tåg/spf, nedsättningar.',NULL,33,0,'initial'),
('chef-1','op','chef','Attityd/ Inställning. Följer regler, rapporterar olyckor/tillbud, samspel med andra funktioner.','',NULL,34,0,'initial'),
('chef-2','op','chef','Följer regler i styrande dokument, hittar styrande dokument. Var finns tdokar. Var finns säkerhetsplaner för olika driftplatser?','',NULL,35,0,'initial'),
('chef-3','op','chef','Samtalsdisciplin. Korrekta termer, tydliga samtal, rätt identifikation.','',NULL,36,0,'initial'),
