('chef-5','op','chef','Olyckshantering. Hantering olycka, tillbud, avvikelse. Vet var uppgift om farligt gods finns. Kan nödfrånkoppla kontaktledningen.','',NULL,38,0,'initial'),
('chef-6','op','chef','Dokumentation. Korrekt dokumentation med betydelse för säkerheten. Skrivit in sig i graf, tkl-bok.','',NULL,39,0,'initial'),
